var solanaTestEnvironment = cre.Environment{
	ChainSelector:   16015286601757825753,
	RegistryAddress: "0x7f3191eaf73429177bab3bac5c36ed2d5e39985f",
}

type solanaTestNode struct {
	nodeOperatorID uint32
	evmKey         *ecdsa.PrivateKey
	solanaKey      *ecdsa.PrivateKey
}

// solanaTestDON builds a DON whose consensus OCR3 config publishes multichain (EVM + Solana) signers.
type solanaTestDON struct {
	f     uint8
	nodes []solanaTestNode
	// ocrSigners overrides the OCR3 signers written to the consensus capability config when non-nil.
	ocrSigners [][]byte
	// capabilityID overrides the consensus capability ID when non-empty.
	capabilityID string
}

func newSolanaTestDON(t *testing.T, n int, f uint8) *solanaTestDON {
	don := &solanaTestDON{f: f}
	for i := 0; i < n; i++ {
		evmKey, err := crypto.GenerateKey()
		require.NoError(t, err)
		solanaKey, err := crypto.GenerateKey()
		require.NoError(t, err)
		don.nodes = append(don.nodes, solanaTestNode{nodeOperatorID: uint32(100 + i), evmKey: evmKey, solanaKey: solanaKey})
	}
	return don
}

func (d *solanaTestDON) sign(t *testing.T, nodes ...int) [][]byte {
	h := sha256.New()
	h.Write([]byte{byte(len(rawReport))})
	h.Write(rawReport)
	h.Write(reportContext)
	digest := h.Sum(nil)

	sigs := make([][]byte, len(nodes))
	for i, idx := range nodes {
		sig, err := crypto.Sign(digest, d.nodes[idx].solanaKey)
		require.NoError(t, err)
		sigs[i] = sig
	}
	return sigs
}

func multichainKey(keys ...[]byte) []byte {
	var out []byte
	chainTypes := []byte{1, 2} // EVM, Solana
	for i, key := range keys {
		out = append(out, chainTypes[i])
		out = binary.LittleEndian.AppendUint16(out, uint16(len(key)))
		out = append(out, key...)
	}
	return out
}

func (d *solanaTestDON) consensusConfig() []byte {
	signers := d.ocrSigners
	if signers == nil {
		for _, node := range d.nodes {
			signers = append(signers, multichainKey(
				crypto.PubkeyToAddress(node.evmKey.PublicKey).Bytes(),
				crypto.PubkeyToAddress(node.solanaKey.PublicKey).Bytes(),
			))
		}
	}

	// OCR3Config{signers: 1, f: 3}
	var ocr3Config []byte
	for _, signer := range signers {
		ocr3Config = protowire.AppendTag(ocr3Config, 1, protowire.BytesType)
		ocr3Config = protowire.AppendBytes(ocr3Config, signer)
	}
	ocr3Config = protowire.AppendTag(ocr3Config, 3, protowire.VarintType)
	ocr3Config = protowire.AppendVarint(ocr3Config, uint64(d.f))

	// map<string, OCR3Config> entry
	var entry []byte
	entry = protowire.AppendTag(entry, 1, protowire.BytesType)
	entry = protowire.AppendString(entry, "__default__")
	entry = protowire.AppendTag(entry, 2, protowire.BytesType)
	entry = protowire.AppendBytes(entry, ocr3Config)

	// CapabilityConfig{local_only: 8, ocr3_configs: 9}
	var config []byte
	config = protowire.AppendTag(config, 8, protowire.VarintType)
	config = protowire.AppendVarint(config, 1)
	config = protowire.AppendTag(config, 9, protowire.BytesType)
	config = protowire.AppendBytes(config, entry)
	return config
}

type capabilityConfiguration struct {
	CapabilityId string
	Config       []byte
}

type donInfoABI struct {
	Id                       uint32
	ConfigCount              uint32
	F                        uint8
	IsPublic                 bool
	AcceptsWorkflows         bool
	NodeP2PIds               [][32]byte
	DonFamilies              []string
	Name                     string
	Config                   []byte
	CapabilityConfigurations []capabilityConfiguration
}

type nodeInfoABI struct {
	NodeOperatorId      uint32
	ConfigCount         uint32
	WorkflowDONId       uint32
	Signer              [32]byte
	P2pId               [32]byte
	EncryptionPublicKey [32]byte
	CsaKey              [32]byte
	CapabilityIds       []string
	CapabilitiesDONIds  []*big.Int
}

// responses returns the getDON and getNodesByP2PIds ABI responses for the DON.
func (d *solanaTestDON) responses(t *testing.T) [][]byte {
	abiJSON, err := os.ReadFile("capreg_abi.json")
	require.NoError(t, err)
	parsed, err := abi.JSON(bytes.NewReader(abiJSON))
	require.NoError(t, err)

	capabilityID := d.capabilityID
	if capabilityID == "" {
		capabilityID = "consensus@1.0.0-alpha"
	}

	don := donInfoABI{
		Id:               reportDONID,
		ConfigCount:      reportDONCfgVer,
		F:                d.f,
		AcceptsWorkflows: true,
		DonFamilies:      []string{},
		Name:             "solana-test",
		Config:           []byte{},
		CapabilityConfigurations: []capabilityConfiguration{
			{CapabilityId: "cron-trigger@1.0.0", Config: []byte{0x40, 0x01}},
			{CapabilityId: capabilityID, Config: d.consensusConfig()},
		},
	}
	var nodes []nodeInfoABI
	for i, node := range d.nodes {
		var p2pID, signer [32]byte
		p2pID[0] = byte(i + 1)
		copy(signer[:], crypto.PubkeyToAddress(node.evmKey.PublicKey).Bytes())
		don.NodeP2PIds = append(don.NodeP2PIds, p2pID)
		nodes = append(nodes, nodeInfoABI{
			NodeOperatorId:     node.nodeOperatorID,
			ConfigCount:        1,
			WorkflowDONId:      reportDONID,
			Signer:             signer,
			P2pId:              p2pID,
			CapabilityIds:      []string{},
			CapabilitiesDONIds: []*big.Int{},
		})
	}

	getDON, err := parsed.Methods["getDON"].Outputs.Pack(don)
	require.NoError(t, err)
	getNodes, err := parsed.Methods["getNodesByP2PIds"].Outputs.Pack(nodes)
	require.NoError(t, err)
	return [][]byte{getDON, getNodes}
}

// orderedCallContractMock answers CallContract requests in order, checking only the function selector.
type orderedCallContractMock struct {
	chainSelector uint64
	selectors     [][]byte
	responses     [][]byte
	actualCalls   int
}

func (m *orderedCallContractMock) Invoke(_ context.Context, request *sdk.CapabilityRequest) *sdk.CapabilityResponse {
	callIdx := m.actualCalls
	m.actualCalls++
	if callIdx >= len(m.responses) {
		return &sdk.CapabilityResponse{Response: &sdk.CapabilityResponse_Error{Error: fmt.Sprintf("unexpected call %d", callIdx)}}
	}
	if !bytes.Contains(request.GetPayload().GetValue(), m.selectors[callIdx]) {
		return &sdk.CapabilityResponse{Response: &sdk.CapabilityResponse_Error{Error: fmt.Sprintf("call %d: missing selector %x", callIdx, m.selectors[callIdx])}}
	}

	var reply []byte
	reply = protowire.AppendTag(reply, 1, protowire.BytesType)
	reply = protowire.AppendBytes(reply, m.responses[callIdx])
	return &sdk.CapabilityResponse{Response: &sdk.CapabilityResponse_Payload{Payload: &anypb.Any{
		TypeUrl: "type.googleapis.com/capabilities.blockchain.evm.v1alpha.CallContractReply",
		Value:   reply,
	}}}
}

func (m *orderedCallContractMock) ID() string {
	return fmt.Sprintf("evm:ChainSelector:%d@1.0.0", m.chainSelector)
}

func setupSolanaDONRead(t *testing.T, don *solanaTestDON) *orderedCallContractMock {
	cre.ClearRepostSignatureCache()
	mock := &orderedCallContractMock{
		chainSelector: solanaTestEnvironment.ChainSelector,
		selectors:     [][]byte{{0x23, 0x53, 0x74, 0x05}, {0x05, 0xa5, 0x19, 0x66}},
		responses:     don.responses(t),
	}
	require.NoError(t, registry.GetRegistry(t).RegisterCapability(mock))
	return mock
}

func solanaConfig() cre.ReportParseConfig {
	return cre.ReportParseConfig{
		AcceptedEnvironments: []cre.Environment{solanaTestEnvironment},
		Encoder:              cre.EncoderSolana,
	}
}

func Test_ParseReportWithConfig_Solana(t *testing.T) {
	t.Run("valid report", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		sigs := don.sign(t, 2, 0)
		report, err := cre.ParseReportWithConfig(runtime, rawReport, sigs, reportContext, solanaConfig())

		require.NoError(t, err)
		accepted := report.X_GeneratedCodeOnly_Unwrap().Sigs
		require.Len(t, accepted, 2)
		assert.Equal(t, sigs[0], accepted[0].Signature)
		assert.Equal(t, don.nodes[2].nodeOperatorID, accepted[0].SignerId)
		assert.Equal(t, don.nodes[0].nodeOperatorID, accepted[1].SignerId)
	})

	t.Run("encoder is case-insensitive", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		config := solanaConfig()
		config.Encoder = "Solana"
		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 1), reportContext, config)

		require.NoError(t, err)
	})

	t.Run("VerifySignaturesWithConfig verifies a parsed report", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		config := solanaConfig()
		config.SkipSignatureVerification = true
		report, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 1), reportContext, config)
		require.NoError(t, err)

		require.NoError(t, report.VerifySignaturesWithConfig(runtime, solanaConfig()))
	})

	t.Run("signatures from the nodes' evm keys are rejected", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		evmSigners := &solanaTestDON{nodes: []solanaTestNode{
			{solanaKey: don.nodes[0].evmKey},
			{solanaKey: don.nodes[1].evmKey},
		}}
		_, err := cre.ParseReportWithConfig(runtime, rawReport, evmSigners.sign(t, 0, 1), reportContext, solanaConfig())

		require.ErrorIs(t, err, cre.ErrUnknownSigner)
	})

	t.Run("evm encoder rejects solana signatures", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		config := solanaConfig()
		config.Encoder = cre.EncoderEVM
		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 1), reportContext, config)

		require.ErrorIs(t, err, cre.ErrUnknownSigner)
	})

	t.Run("too few signatures fails validation", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0), reportContext, solanaConfig())

		require.ErrorIs(t, err, cre.ErrWrongSignatureCount)
	})

	t.Run("duplicated signatures fails validation", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 0), reportContext, solanaConfig())

		require.ErrorIs(t, err, cre.ErrDuplicateSigner)
	})

	t.Run("signer outside the DON fails validation", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		outsider := newSolanaTestDON(t, 1, 1)
		sigs := append(don.sign(t, 0), outsider.sign(t, 0)...)
		_, err := cre.ParseReportWithConfig(runtime, rawReport, sigs, reportContext, solanaConfig())

		require.ErrorIs(t, err, cre.ErrUnknownSigner)
	})

	t.Run("OCR3 signer whose evm key is not a DON node is ignored", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		outsider := newSolanaTestDON(t, 1, 1)
		// Publish the outsider's Solana key paired with an EVM key that is not registered for the DON.
		don.ocrSigners = [][]byte{
			multichainKey(crypto.PubkeyToAddress(don.nodes[0].evmKey.PublicKey).Bytes(), crypto.PubkeyToAddress(don.nodes[0].solanaKey.PublicKey).Bytes()),
			multichainKey(crypto.PubkeyToAddress(outsider.nodes[0].evmKey.PublicKey).Bytes(), crypto.PubkeyToAddress(outsider.nodes[0].solanaKey.PublicKey).Bytes()),
		}
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		sigs := append(don.sign(t, 0), outsider.sign(t, 0)...)
		_, err := cre.ParseReportWithConfig(runtime, rawReport, sigs, reportContext, solanaConfig())

		require.ErrorIs(t, err, cre.ErrUnknownSigner)
	})

	t.Run("DON without solana signers returns an error", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		don.ocrSigners = [][]byte{}
		for _, node := range don.nodes {
			don.ocrSigners = append(don.ocrSigners, multichainKey(crypto.PubkeyToAddress(node.evmKey.PublicKey).Bytes()))
		}
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 1), reportContext, solanaConfig())

		require.ErrorContains(t, err, "no solana signers for DON 1")
		require.ErrorContains(t, err, "consensus OCR3 config has no solana signers")
	})

	t.Run("DON without consensus capability returns an error", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		don.capabilityID = "not-consensus@1.0.0"
		setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 1), reportContext, solanaConfig())

		require.ErrorContains(t, err, "consensus capability is not configured on the DON")
	})

	t.Run("DON info is cached across encoders", func(t *testing.T) {
		don := newSolanaTestDON(t, 4, 1)
		mock := setupSolanaDONRead(t, don)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		_, err := cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 0, 1), reportContext, solanaConfig())
		require.NoError(t, err)
		_, err = cre.ParseReportWithConfig(runtime, rawReport, don.sign(t, 2, 3), reportContext, solanaConfig())
		require.NoError(t, err)

		assert.Equal(t, 2, mock.actualCalls)
	})
}

func Test_ParseReportWithConfig_SolanaEncoderWithoutConsensusOCR3Config(t *testing.T) {
	// productionEnvironmentReplay was recorded before DON 1 published its consensus OCR3 config on the registry,
	// so solana verification must fail with a clear error while EVM verification keeps working.
	setupDonSettingRead(t, productionEnvironmentReplay)
	runtime := testutils.NewRuntime(t, testutils.Secrets{})

	config := cre.ReportParseConfig{
		AcceptedEnvironments: []cre.Environment{cre.ProductionEnvironment()},
		Encoder:              cre.EncoderSolana,
	}
	_, err := cre.ParseReportWithConfig(runtime, rawReport, reportSigs, reportContext, config)
	require.ErrorContains(t, err, "no solana signers for DON 1")

	report, err := cre.ParseReport(runtime, rawReport, reportSigs, reportContext)
	require.NoError(t, err)
	require.NotNil(t, report)
}

