func mustDecodeBase64(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return b
}

func Test_ParseReportWithConfig_SolanaProductionReport(t *testing.T) {
	config := cre.ReportParseConfig{
		AcceptedEnvironments: []cre.Environment{cre.ProductionEnvironment()},
		Encoder:              cre.EncoderSolana,
	}

	t.Run("valid report", func(t *testing.T) {
		setupDonSettingRead(t, zoneASolanaReplay)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		report, err := cre.ParseReportWithConfig(runtime, solanaRawReport, solanaReportSigs, solanaReportContext, config)

		require.NoError(t, err)
		accepted := report.X_GeneratedCodeOnly_Unwrap().Sigs
		require.Len(t, accepted, len(solanaReportSigIds))
		for i, sig := range accepted {
			assert.Equal(t, solanaReportSigs[i], sig.Signature)
			assert.Equal(t, solanaReportSigIds[i], sig.SignerId)
		}
	})

	t.Run("evm encoder rejects the report", func(t *testing.T) {
		setupDonSettingRead(t, zoneASolanaReplay)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		evmConfig := config
		evmConfig.Encoder = cre.EncoderEVM
		_, err := cre.ParseReportWithConfig(runtime, solanaRawReport, solanaReportSigs, solanaReportContext, evmConfig)

		require.ErrorIs(t, err, cre.ErrUnknownSigner)
	})

	t.Run("tampered report fails validation", func(t *testing.T) {
		setupDonSettingRead(t, zoneASolanaReplay)
		runtime := testutils.NewRuntime(t, testutils.Secrets{})

		tampered := bytes.Clone(solanaRawReport)
		tampered[len(tampered)-1] ^= 1
		_, err := cre.ParseReportWithConfig(runtime, tampered, solanaReportSigs, solanaReportContext, config)

		require.ErrorIs(t, err, cre.ErrUnknownSigner)
	})
}
